// Medical Reading Practice Test 1. Original questions written for Valus for the five 2026–27 HOSA books.
// Like the Valus Medical Reading lessons, these questions do not claim to report specific chapters,
// passages or patients from the copyrighted books. They test the background science, concepts and
// reading-analysis skills each book draws on; students should study the books themselves for details.
import {q, mix} from './q.js';
const CA='Crisis Averted (Rivers)', TB='Everything Is Tuberculosis (Green)', FR='Fragmented (Yurkiewicz)', NP='The Next Patient (Grant)', GR='Grit (Duckworth)';
const CDC='CDC', WHO='World Health Organization', AHRQ='Agency for Healthcare Research and Quality', DUCK='Duckworth et al., grit research publications', VAL='Valus Medical Reading lessons';

export default {
 id:'medical-reading-1',
 event:'Medical Reading',
 title:'Practice Test 1',
 subtitle:'Background and ideas behind the five assigned books',
 minutes:60,
 sources:'the five assigned books’ subject areas, with background from the CDC, WHO, AHRQ and published grit research (study the books for chapter details)',
 plan:[{area:CA,weight:20},{area:TB,weight:20},{area:FR,weight:20},{area:NP,weight:20},{area:GR,weight:20}],
 questions:mix([
  q(CA,'Why is successful outbreak prevention often called “invisible”?','The prevented crisis never visibly happens',['Prevention work is kept secret by law','Outbreaks are always too small to measure','Public health workers avoid publicity'],'B','Judging prevention requires a counterfactual: estimating what would have happened without the action.',VAL),
  q(CA,'In evaluating a public health response, what is a counterfactual?','What would have happened otherwise',['The actual number of cases reported','A false claim made in the media','The cost of the response'],'D','Comparing what happened with a reasonable estimate of what would have happened is how the impact of prevention is judged.',VAL),
  q(CA,'What does the basic reproduction number (R₀) describe?','Average infections caused by one case',['The number of deaths from the disease','The time from infection to symptoms','The number of vaccines needed per person'],'A','An R₀ above 1 means an outbreak can grow; interventions aim to push the effective reproduction number below 1.',CDC),
  q(CA,'Outbreak forecasters build models of how a disease might spread. Why are their projections given as ranges?','Spread depends on uncertain factors',['Forecasters lack enough computing power','Ranges are required by federal law','Models always predict the exact number'],'C','Scenario ranges communicate uncertainty and help leaders plan for best and worst cases.',CDC),
  q(CA,'Which action is an example of a nonpharmaceutical intervention during an outbreak?','Isolation and better ventilation',['Giving a new antiviral drug','Developing a new vaccine','Prescribing antibiotics early'],'B','Nonpharmaceutical interventions slow spread without medicines, through measures such as isolation, masking, ventilation and distancing.',CDC),
  q(CA,'How does disease surveillance help prevent crises?','It detects unusual patterns early',['It treats patients directly','It replaces the need for hospitals','It prevents all infections automatically'],'D','Timely data on cases, lab results or even wastewater can reveal an outbreak before it grows large.',CDC),
  q(CA,'Why can it be hard to win public support for spending on outbreak preparedness?','Costs are immediate; benefits uncertain',['Preparedness has no real costs','Major outbreaks never really happen','The public always opposes science'],'C','Leaders must justify spending today against risks that may not appear for years.',VAL),
  q(CA,'A local health department finds every contact of a new case and asks them to quarantine. What is this activity?','Contact tracing',['Herd immunity','Syndromic surveillance','Vaccine distribution'],'A','Contact tracing interrupts chains of transmission by identifying exposed people early.',CDC),
  q(CA,'An author writes that a response “likely prevented thousands of cases.” What should a careful reader check?','The method behind the estimate',['Whether the author is well known','Whether the number sounds large','Whether other books repeat it'],'B','Estimates of prevented cases depend on models and assumptions. Critical readers look for the evidence behind a claim.',VAL),
  q(CA,'Which communication principle helps public health officials keep trust during an evolving outbreak?','Being transparent about what is known and unknown',['Never admitting uncertainty','Releasing information only after the crisis ends','Using only technical jargon'],'D','Honest, timely communication about uncertainty supports trust when guidance has to change.',CDC),
  q(TB,'Which organism causes tuberculosis?','Mycobacterium tuberculosis',['Streptococcus pneumoniae','Influenza virus','Plasmodium falciparum'],'A','Robert Koch identified the bacterium in 1882; it grows slowly and has a waxy cell wall that resists many drugs.',CDC),
  q(TB,'How is tuberculosis usually spread?','Through the air from active lung TB',['Through contaminated food','Through infected mosquito bites','Through casual touching of surfaces'],'C','TB spreads through airborne droplet nuclei from people with infectious pulmonary disease.',CDC),
  q(TB,'How does TB infection (latent TB) differ from TB disease?','TB infection is symptom-free and not contagious',['TB infection is always more contagious','TB infection causes severe coughing','There is no real difference between them'],'B','People with TB infection can progress to TB disease later, so treatment may be recommended to prevent it.',CDC),
  q(TB,'Multidrug-resistant TB does not respond to which two key first-line drugs?','Isoniazid and rifampicin',['Penicillin and amoxicillin','Acetaminophen and ibuprofen','Insulin and metformin'],'D','MDR-TB requires longer or more complex treatment. Incomplete treatment helps drug resistance develop.',WHO),
  q(TB,'What is directly observed therapy (DOT)?','A health worker supports each dose',['A doctor watching a chest X-ray','A patient taking pills only when sick','A surgery to remove infected lung'],'A','TB treatment lasts months, and DOT helps people finish it, which cures the patient and prevents resistance.',WHO),
  q(TB,'According to the WHO, how does tuberculosis rank among infectious diseases worldwide?','A leading infectious cause of death',['It has been eradicated worldwide','It now affects only animals','It causes no deaths each year'],'C','TB remains a leading infectious killer, especially in low- and middle-income countries, even though it is curable.',WHO),
  q(TB,'Why does a curable disease like TB persist in many parts of the world?','Poverty and unequal access to care',['There is no treatment for TB','TB affects only wealthy countries','TB vaccines work perfectly'],'B','Social factors such as poverty, crowding, malnutrition and weak health systems keep TB common where resources are scarce.',WHO),
  q(TB,'Which vaccine against TB is widely given to infants in countries where TB is common?','BCG',['MMR','HPV','DTaP'],'D','The BCG vaccine protects young children from severe forms of TB but offers limited protection to adults.',WHO),
  q(TB,'A book combines one patient’s story with chapters of history and science. What is this structure often called?','A braided narrative',['A dictionary','A lab report','A single-perspective diary'],'A','Braiding personal and historical threads lets each one explain the other. Readers track how the threads connect.',VAL),
  q(TB,'In the 1800s, why were patients with TB often sent to sanatoriums?','For rest, fresh air and isolation',['For surgery on every patient','To receive streptomycin injections','To join research trials'],'C','Effective drug treatment did not arrive until the 1940s, beginning with streptomycin.',CDC),
  q(FR,'What does care fragmentation mean?','Poorly coordinated care across many settings',['Care provided by only one primary doctor','Care that is always free of charge','Care that happens only in emergencies'],'B','Fragmentation can cause missed information, repeated tests and errors.',AHRQ),
  q(FR,'What is a handoff in health care?','Passing care to another clinician',['A greeting between staff members','A type of surgical instrument','A patient’s payment at discharge'],'D','Handoffs happen at shift changes and transfers, and they are common points for communication failures.',AHRQ),
  q(FR,'Which handoff tool ends with the receiver summarizing the information back?','I-PASS',['SBAR report','SOAP','ABCDE'],'A','I-PASS stands for Illness severity, Patient summary, Action list, Situation awareness and contingency planning, and Synthesis by receiver.',AHRQ),
  q(FR,'What does continuity of care mean?','Connected care over time with a known clinician',['Each visit is with a new clinician','Care happens continuously in one hospital','Patients manage all of their care alone'],'C','Continuity helps clinicians know a patient’s history and follow up on problems.',AHRQ),
  q(FR,'A scan for one problem reveals an unrelated spot on the kidney. What is this called?','An incidental finding',['A primary diagnosis','A shift handoff','A sentinel event'],'B','Incidental findings often fall between teams, so no one clearly owns the follow-up.',VAL),
  q(FR,'Why can electronic health records still leave care fragmented?','Systems may not share information',['Electronic records cannot store data','Doctors are not allowed to read them','They always contain too little information'],'D','Different systems that cannot exchange data reproduce fragmentation in digital form.',AHRQ),
  q(FR,'In an argument, what is the warrant?','Reasoning linking evidence to the claim',['The author’s main conclusion','The data presented as support','The title of the chapter itself'],'A','Warrants are often unstated. Readers test whether the evidence really supports the claim.',VAL),
  q(FR,'A clinician-author describes years of practice to support her argument. Which appeal is she using?','Ethos (credibility)',['Pathos (emotion)','Logos (logic)','Kairos (timing)'],'C','Ethos relies on the speaker’s credibility. Pathos uses emotion, and logos uses logic and data.',VAL),
  q(FR,'Which question best evaluates an author’s proposed solution to fragmented care?','What evidence shows it would work?',['Is the author well known in medicine?','Is the solution short to describe?','Does the author sound confident?'],'B','Strong evaluation weighs evidence, feasibility, costs and possible downsides.',VAL),
  q(FR,'A memoir mixes the author’s feelings of frustration with arguments for change. What should a reader distinguish?','Reflection from evidence-backed claims',['Fiction from nonfiction poetry','Chapter titles from page numbers','The author’s age from her name'],'D','Both matter, but they are evaluated differently: reflection shows experience, while argument needs support.',VAL),
  q(NP,'What is the purpose of triage in an emergency department?','Deciding who is seen first',['Treating patients in order of arrival','Billing patients before treatment','Choosing which doctor is on duty'],'A','Triage directs limited resources to the most urgent patients first.',AHRQ),
  q(NP,'How many levels does the Emergency Severity Index (ESI) use?','Five',['Two','Three','Ten'],'C','ESI ranks patients from level 1 (most urgent, needs immediate lifesaving care) to level 5 (least resource-intensive).',AHRQ),
  q(NP,'Which federal law requires hospitals that accept Medicare to screen and stabilize emergency patients regardless of ability to pay?','EMTALA',['HIPAA','The ACA','OSHA'],'B','The Emergency Medical Treatment and Labor Act prevents emergency departments from turning away or “dumping” patients.',CDC),
  q(NP,'What is ED “boarding”?','Keeping admitted patients in the ED',['Training new emergency residents','Transferring patients by helicopter','Discharging patients early'],'D','Boarding contributes to crowding, longer waits and strain on staff.',AHRQ),
  q(NP,'A doctor fixes on the first diagnosis that comes to mind and does not adjust as new information arrives. What bias is this?','Anchoring',['Availability bias','Hindsight bias','Framing'],'A','Anchoring is a common cognitive bias in diagnosis. Deliberately considering alternatives helps counter it.',AHRQ),
  q(NP,'Accepting a diagnosis before it has been fully verified is called:','Premature closure',['Diagnostic momentum reversal','Triage','Overshadowing'],'C','Premature closure stops the search for other explanations too early.',AHRQ),
  q(NP,'A patient with a known mental health condition has new chest pain that is blamed on anxiety without a full workup. What bias is this?','Diagnostic overshadowing',['Anchoring on lab values','Framing','Recency bias'],'B','A known condition can lead clinicians to attribute new symptoms to it and miss other causes.',AHRQ),
  q(NP,'Why must emergency clinicians practice “simultaneity”?','They manage several patients at once',['They work only one shift a year','They see one patient per day','They never work in teams'],'D','Emergency care requires prioritizing and switching between patients while tracking each one’s needs.',VAL),
  q(NP,'Why can a story about a missed diagnosis make the right answer seem obvious?','Hindsight makes uncertainty look clear',['The doctor ignored every test','All diagnoses are simple to make','The patient told the doctor the answer'],'A','Readers know the outcome; clinicians in real time faced uncertainty.',VAL),
  q(NP,'How do the National Academies define diagnostic error?','Not giving a patient an accurate, timely explanation',['Any lab result outside the normal range','A patient refusing recommended treatment','A doctor working a double shift'],'C','The definition includes both reaching the right diagnosis in time and explaining it to the patient.',AHRQ),
  q(GR,'How did Duckworth and colleagues define grit?','Perseverance and passion for long-term goals',['Natural talent and intelligence','Short-term motivation for quick rewards','Physical strength and stamina'],'B','They developed a self-report questionnaire, the Grit Scale, to measure it.',DUCK),
  q(GR,'Which two components make up grit in this research?','Perseverance and consistent interests',['High IQ and strong memory','Speed and accuracy on tests','Confidence and charisma'],'D','Perseverance is continuing despite setbacks; consistency of interests is staying focused on the same goals over time.',DUCK),
  q(GR,'Later research found that grit overlaps substantially with which personality trait?','Conscientiousness',['Extraversion','Neuroticism','Openness to experience'],'A','Meta-analyses found grit is closely related to conscientiousness and its link to performance is more modest than early reports suggested.',DUCK),
  q(GR,'Focused practice on specific weaknesses, with clear goals and immediate feedback, is called:','Deliberate practice',['Passive review','Mindless repetition','Cramming'],'C','Deliberate practice differs from simply spending more hours on an activity.',DUCK),
  q(GR,'Hearing only from people who persisted and succeeded, but not from those who persisted and failed, can produce which bias?','Survivorship bias',['Confirmation bias','Anchoring','Framing'],'B','Success stories alone can make a trait look more important than it is.',VAL),
  q(GR,'Students with high grit scores tend to have higher grades. What can be concluded from this alone?','They are correlated; cause is unproven',['Grit definitely causes higher grades','Higher grades must cause grit','There is no relationship'],'D','Confounding variables could affect both. Causal claims need experiments or stronger study designs.',VAL),
  q(GR,'A grit questionnaire gives similar scores when the same students take it twice. What property does this show?','Reliability',['Validity','Causation','Generalizability'],'A','Reliability is consistency. Validity is whether the test measures what it claims to measure.',VAL),
  q(GR,'What is a growth mindset?','The belief that abilities can be developed',['The belief that intelligence is fixed','A plan to grow a small business','A feeling of overconfidence'],'C','Growth mindset research has influenced education, though large studies show effects that are real but often small.',VAL),
  q(GR,'Which study strategy strengthens long-term memory more than rereading notes?','Retrieval practice',['Highlighting every line','Reading faster','Studying only the night before'],'B','Recalling information from memory strengthens learning. Spaced practice and interleaving also help.',VAL),
  q(GR,'A self-report questionnaire asks students to rate their own persistence. What is one limitation?','People may rate themselves inaccurately',['It always measures intelligence','It cannot be scored','It requires a blood sample'],'D','Self-reports can be affected by social desirability and self-perception, so other measures can add evidence.',DUCK)
 ],199)
};
